// netlify/functions/referral-pdf.js
// Generates a completed MD Uniform Consultation Referral Form PDF.
// POST { key, provider, date, patient:{name,dob,phone,member},
//        carrier:{name,address,phone,fax},
//        consultant:{name,specialty,org,address,phone,fax},
//        referral:{reason,history,services:[],specify:{},place:[],facility,visits,auth,validUntil} }
// Returns { pdf: <base64> }
// Requires dependency: pdf-lib (in package.json). Env: DASH_KEY (optional gate).

const { PDFDocument, rgb } = require('pdf-lib');

const PROVIDERS = {
  amaris:  { name: 'Murray, Amaris',  spec: 'Family Medicine — CRNP' },
  yahaira: { name: 'Matias, Yahaira', spec: 'Family Medicine — CRNP' },
};
const PRACTICE = {
  org: 'Baltimore Healthcare & Wellness, LLC (BHW Medical Group)',
  npi: 'NPI 1306511597',
  addr: '2131 Maryland Ave, Baltimore, MD 21218',
  phoneArea: '443', phoneNum: '7625343',
  faxArea: '833',  faxNum: '2583941',
};
const d10 = s => (s || '').replace(/\D/g, '').slice(-10);

exports.handler = async (event) => {
  try {
    if (event.httpMethod !== 'POST') return { statusCode: 405, body: 'POST only' };
    const b = JSON.parse(event.body || '{}');
    if (process.env.DASH_KEY && b.key !== process.env.DASH_KEY)
      return { statusCode: 401, body: 'bad key' };

    const doc = await PDFDocument.load(Buffer.from(BASE_PDF, 'base64'));
    const page = doc.getPages()[0];
    const form = doc.getForm();
    const set = (n, v) => { if (v == null || v === '') return;
      try { form.getTextField(n).setText(String(v)); } catch (e) {} };
    const chk = (n) => { try { form.getCheckBox(n).check(); } catch (e) {} };

    // ---- white-out pre-printed Aetna carrier info, draw the chosen carrier ----
    const white = rgb(1, 1, 1);
    page.drawRectangle({ x: 344, y: 655, width: 246, height: 16, color: white });
    page.drawRectangle({ x: 344, y: 621, width: 246, height: 26, color: white });
    page.drawRectangle({ x: 344, y: 599, width: 246, height: 15, color: white });
    page.drawRectangle({ x: 344, y: 587, width: 246, height: 15, color: white });
    const c = b.carrier || {};
    const draw = (t, x, y, size) => { if (t) page.drawText(String(t).slice(0, 60), { x, y, size: size || 8.5 }); };
    draw(c.name, 346, 659);
    const addr = String(c.address || '');
    draw(addr.slice(0, 45), 346, 637);
    draw(addr.slice(45, 95), 346, 626);
    draw(c.phone, 346, 603);
    draw(c.fax, 346, 590);

    // ---- date + patient block ----
    const p = b.patient || {};
    set('Text1.0', b.date || new Date().toLocaleDateString('en-US'));
    set('Text1.1', p.name);
    set('Text1.2', p.dob);
    const pp = d10(p.phone);
    if (pp.length === 10) { set('Text1.3', pp.slice(0, 3)); set('Text1.4', pp.slice(3)); }
    set('Text1.5', p.member);

    // ---- requesting provider block ----
    const pr = PROVIDERS[b.provider] || PROVIDERS.amaris;
    set('Text1.13', pr.name);  set('Text1.14', pr.spec);
    set('Text1.15', PRACTICE.org);  set('Text1.17', PRACTICE.npi);
    set('Text1.18', PRACTICE.addr);
    set('Text1.19', PRACTICE.phoneArea); set('Text1.20', PRACTICE.phoneNum);
    set('Text1.21', PRACTICE.faxArea);   set('Text1.22', PRACTICE.faxNum);

    // ---- consultant block (from Specialist Directory) ----
    const s = b.consultant || {};
    set('Text1.23', s.name);  set('Text1.24', s.specialty);
    set('Text1.25', s.org);   set('Text1.28', s.address);
    const sp = d10(s.phone), sf = d10(s.fax);
    if (sp.length === 10) { set('Text1.29', sp.slice(0, 3)); set('Text1.30', sp.slice(3)); }
    if (sf.length === 10) { set('Text1.31', sf.slice(0, 3)); set('Text1.32', sf.slice(3)); }

    // ---- referral information ----
    const r = b.referral || {};
    set('Text1.33', r.reason);
    set('Text1.34', r.history);
    const sv = r.services || [], sx = r.specify || {};
    const svcMap = { initial:'Check Box2.0', diagnostic:'Check Box2.1', procedures:'Check Box2.2',
                     treatment:'Check Box2.3', globalob:'Check Box2.4', other:'Check Box2.5' };
    sv.forEach(k => chk(svcMap[k]));
    set('Text1.35', sx.diagnostic); set('Text1.36', sx.procedures);
    set('Text1.38', sx.treatment);  set('Text1.39', sx.other);
    const plMap = { office:'Check Box2.6', outpatient:'Check Box2.7', radiology:'Check Box2.8',
                    laboratory:'Check Box2.9', inpatient:'Check Box2.10', extended:'Check Box2.11', pother:'Check Box2.12' };
    (r.place || []).forEach(k => chk(plMap[k]));
    set('Text1.44', r.placeOther);
    set('Text1.45', r.facility);
    set('Text1.42', r.visits);
    set('Text1.43', r.auth);
    set('Text1.46', r.validUntil);

    form.updateFieldAppearances();
    const out = await doc.save();
    return {
      statusCode: 200,
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ pdf: Buffer.from(out).toString('base64') }),
    };
  } catch (e) {
    return { statusCode: 500, body: String(e) };
  }
};

